with (P/'terms.tsv').open('a') as f:
 for en,zh,n in [("The Emperor’s Champion",'帝皇勇士','与普通战团冠军及混沌冠军分开。'),('Marshal','元帅','黑色圣堂完整单位名；其他组织元帅须按语境。'),('Castellan','堡主','黑色圣堂完整单位；不是堡主骑士等载具。'),('Sword Brother','圣剑兄弟会修士','小队构成内直接对照人员名。')]:f.write('\t'.join([en,zh,'官方已核对',urls,'GW09简中第10页；GW10英文第10页',n])+'\n')
 for en,zh,loc,n in [('Sword Brethren','圣剑兄弟会','第400篇','传统集体名，参照官方Sword Brother词根；非宣称完整集体名直接官译。'),('Primaris Sword Brethren','原铸圣剑兄弟','第400篇B0009','GW09新版中文单位圣剑兄弟，GW10旧英文Primaris Sword Brethren；原铸修饰据源文保留，不能宣称同版完整对应。')]:f.write('\t'.join([en,zh,'官方词根参考·通称待核',urls,loc+'；GW09/GW10第10页',n])+'\n')
 for en,zh,loc,n in [('Torchbearer Fleet','持炬舰队','398 B0049','基里曼传送原铸技术与增援的舰队；沿362已用词。'),('Chapter Keep','战团堡垒','398 B0179','黑色圣堂据点；keep作名词。'),('Gervahrt Repeal','格瓦尔特罢黜事件','398 B0138','暂译；与399 Gervhart近似但不强并。'),('Expectanten','候选者','398 B0169','宣称志愿入团、尚未成为Neophyte者。'),('Green Kroosade','绿色远征','398 B0077','欧克口音拼写，非人名。'),('Season of Blood','血之季节','398 B0101','沿395原有事件名，统一鲜血季节异译。')]:f.write('\t'.join([en,zh,'暂定·官方待核','英文底稿','第'+loc,n])+'\n')
